def title_block(ws, title: str, subtitle: str, ncols: int) -> int:
    ws.sheet_view.showGridLines = False
    ws.merge_cells(start_row=1, start_column=1, end_row=1, end_column=ncols)
    c = ws.cell(1, 1, title)
    c.font = Font(name=FONT, size=18, bold=True, color="FFFFFF")
    c.fill = PatternFill("solid", fgColor=NAVY)
    c.alignment = Alignment(vertical="center", indent=1)
    ws.row_dimensions[1].height = 36
    ws.merge_cells(start_row=2, start_column=1, end_row=2, end_column=ncols)
    c = ws.cell(2, 1, subtitle)
    c.font = Font(name=FONT, size=11, italic=True, color=NAVY)
    c.fill = PatternFill("solid", fgColor=PALE)
    c.alignment = Alignment(vertical="center", wrap_text=True, indent=1)
    ws.row_dimensions[2].height = 34
    return 4


def table(ws, start: int, headers: list[str], rows: list[list], widths: list[int], tint: dict[int, tuple[str, str]] | None = None, link_col: int | None = None) -> int:
    """tint: {индекс колонки (0-based): (фон, цвет текста)}"""
    tint = tint or {}
    for j, h in enumerate(headers, 1):
        c = ws.cell(start, j, h)
        c.font = Font(name=FONT, size=11, bold=True, color="FFFFFF")
        c.fill = PatternFill("solid", fgColor=BLUE)
        c.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        c.border = BORDER
        ws.column_dimensions[get_column_letter(j)].width = widths[j - 1]
    ws.row_dimensions[start].height = 32
    for i, row in enumerate(rows, 1):
        r = start + i
        maxlen = 0
        for j, val in enumerate(row, 1):
            c = ws.cell(r, j, val)
            c.font = Font(name=FONT, size=10.5, bold=(j == 2 and not tint), color="1E293B")
            c.alignment = Alignment(vertical="top", wrap_text=True, horizontal="center" if j == 1 else "left")
            c.border = BORDER
            c.fill = PatternFill("solid", fgColor=ZEBRA if i % 2 == 0 else "FFFFFF")
            if (j - 1) in tint:
                bg, tx = tint[j - 1]
                c.fill = PatternFill("solid", fgColor=bg)
                c.font = Font(name=FONT, size=10.5, color=tx)
            if link_col is not None and j - 1 == link_col and isinstance(val, str) and val.startswith("http"):
                c.hyperlink = val
                c.font = Font(name=FONT, size=10, color="0047FF", underline="single")
            if isinstance(val, str):
                maxlen = max(maxlen, len(val) / max(widths[j - 1] * 1.05, 1))
        ws.row_dimensions[r].height = min(max(30, 15.5 * (int(maxlen) + 1)), 230)
    ws.freeze_panes = ws.cell(start + 1, 3)
    ws.auto_filter.ref = f"A{start}:{get_column_letter(len(headers))}{start + len(rows)}"
    return start + len(rows) + 2


def footer(ws, row: int, ncols: int) -> None:
    ws.merge_cells(start_row=row, start_column=1, end_row=row, end_column=ncols)
    c = ws.cell(row, 1, DISCLAIMER)
    c.font = Font(name=FONT, size=9, italic=True, color="64748B")
    c.alignment = Alignment(wrap_text=True, vertical="top", indent=1)
    ws.row_dimensions[row].height = 30


def page(ws, landscape=True) -> None:
    ws.page_setup.orientation = "landscape" if landscape else "portrait"
    ws.page_setup.fitToWidth = 1
    ws.page_setup.fitToHeight = 0
    ws.sheet_properties.pageSetUpPr.fitToPage = True
    ws.print_options.horizontalCentered = True
    ws.oddFooter.center.text = "ДПО-1 · Урок 4 · стр. &P из &N"
    ws.page_margins.left = ws.page_margins.right = 0.4


