def build(path: Path | None = None) -> Path:
    path = path or OUT / "pamyatka_obezlichivanie_dipfeyki_kak_ne_popast.xlsx"
    wb = Workbook()

    # 1 Обзор
    ws = wb.active
    ws.title = "Обзор"
    ws.sheet_properties.tabColor = NAVY
    r = title_block(ws, "Обезличивание, подделки и дипфейки: как не попасть", "ДПО-1 · Урок 4 · шпаргалка на все занятие: принципы, каталог подделок, что делать и чего не делать", 6)
    ws.column_dimensions["A"].width = 30
    for col in "BCDEF":
        ws.column_dimensions[col].width = 26
    rows = [("Принципы обезличивания", f"{len(PRINCIPLES)} принципов с примерами «было → стало», типичной ошибкой и способом проверки"),
            ("Подделки и дипфейки", f"{len(FAKES)} сценариев из материалов курса и реальных случаев: признаки, что делать, чего не делать, источник"),
            ("Как не попасть", f"{len(DONTS)} ситуаций в формате «не делайте / делайте», с обоснованием"),
            ("Реальные случаи", f"{len(CASES)} опубликованных случаев со ссылками на источники"),
            ("Проверка поручения", "Шесть шагов при необычном поручении"),
            ("Чек-лист", f"{len(CHECK)} пунктов самопроверки с выпадающим списком")]
    for name, desc in rows:
        c = ws.cell(r, 1, name)
        c.font = Font(name=FONT, size=11, bold=True, color=NAVY)
        c.fill = PatternFill("solid", fgColor=PALE)
        c.border = BORDER
        c.hyperlink = f"#'{name}'!A1"
        ws.merge_cells(start_row=r, start_column=2, end_row=r, end_column=6)
        d = ws.cell(r, 2, desc)
        d.font = Font(name=FONT, size=10.5)
        d.alignment = Alignment(wrap_text=True, vertical="center")
        d.border = BORDER
        ws.row_dimensions[r].height = 26
        r += 1
    r += 1
    ws.cell(r, 1, "Цветовые обозначения").font = Font(name=FONT, size=12, bold=True, color=NAVY)
    r += 1
    for txt, bg, tx in (("✅ Делайте", GRN_BG, GRN_TX), ("❌ Не делайте", RED_BG, RED_TX), ("⚠ Проверьте", AMB_BG, AMB_TX)):
        c = ws.cell(r, 1, txt)
        c.fill = PatternFill("solid", fgColor=bg)
        c.font = Font(name=FONT, size=11, bold=True, color=tx)
        c.border = BORDER
        r += 1
    r += 1
    ws.merge_cells(start_row=r, start_column=1, end_row=r + 2, end_column=6)
    c = ws.cell(r, 1, "Главное правило: сомневаетесь — считайте красным, остановитесь и спросите ответственного. За результат, который вы подписали и отправили, отвечаете вы, а не нейросеть.")
    c.font = Font(name=FONT, size=13, bold=True, color="FF8901")
    c.alignment = Alignment(wrap_text=True, vertical="center", indent=1)
    footer(ws, r + 4, 6)
    page(ws)

    # 2 Принципы
    ws = wb.create_sheet("Принципы обезличивания")
    ws.sheet_properties.tabColor = BLUE
    start = title_block(ws, "Принципы обезличивания и подготовки данных", "Что делать до отправки данных в ИИ-систему", 7)
    nxt = table(ws, start, ["№", "Принцип", "Что это значит", "Как делать", "Пример «было → стало»", "Типичная ошибка ❌", "Как проверить ✅"],
                [[i + 1] + p for i, p in enumerate(PRINCIPLES)], [5, 28, 34, 40, 36, 34, 34], tint={5: (RED_BG, RED_TX), 6: (GRN_BG, GRN_TX)})
    footer(ws, nxt, 7)
    page(ws)

    # 3 Подделки
    ws = wb.create_sheet("Подделки и дипфейки")
    ws.sheet_properties.tabColor = "C2410C"
    start = title_block(ws, "Подделки, дипфейки и вредоносные сценарии", "Каталог по материалам лекции 1.3, практикумов и реальным случаям", 7)
    nxt = table(ws, start, ["№", "Сценарий", "Как выглядит", "Признаки риска", "Что делать ✅", "Чего не делать ❌", "Источник"],
                [[i + 1] + p for i, p in enumerate(FAKES)], [5, 30, 42, 34, 40, 36, 44], tint={4: (GRN_BG, GRN_TX), 5: (RED_BG, RED_TX)})
    footer(ws, nxt, 7)
    page(ws)

    # 4 Как не попасть
    ws = wb.create_sheet("Как не попасть")
    ws.sheet_properties.tabColor = "B91C1C"
    start = title_block(ws, "Как не попасть: не делайте так — делайте так", "Типичные ситуации и безопасное поведение", 6)
    nxt = table(ws, start, ["№", "Ситуация", "Не делайте ❌", "Делайте ✅", "Почему", "Норма / ориентир"],
                [[i + 1] + p for i, p in enumerate(DONTS)], [5, 22, 44, 46, 38, 36], tint={2: (RED_BG, RED_TX), 3: (GRN_BG, GRN_TX)})
    footer(ws, nxt, 6)
    page(ws)

    # 5 Случаи
    ws = wb.create_sheet("Реальные случаи")
    ws.sheet_properties.tabColor = "0E7490"
    start = title_block(ws, "Реальные случаи с источниками", "Опубликованные в открытых источниках события; ссылки кликабельны", 6)
    nxt = table(ws, start, ["№", "Год", "Случай", "Что произошло", "Урок для работы", "Ссылка"],
                [[i + 1] + p for i, p in enumerate(CASES)], [5, 11, 32, 56, 40, 60], link_col=5)
    footer(ws, nxt, 6)
    page(ws)

    # 6 Поручение
    ws = wb.create_sheet("Проверка поручения")
    ws.sheet_properties.tabColor = "7C3AED"
    start = title_block(ws, "Проверка необычного поручения: шесть шагов", "Работает одинаково для голоса, видео, письма и сообщения в мессенджере", 5)
    nxt = table(ws, start, ["№", "Шаг", "Что делаем", "Кто", "Важно"], FLOW, [5, 30, 60, 20, 46])
    footer(ws, nxt, 5)
    page(ws)

    # 7 Чек-лист
    ws = wb.create_sheet("Чек-лист")
    ws.sheet_properties.tabColor = "16A34A"
    start = title_block(ws, "Чек-лист самопроверки", "Отметьте каждый пункт: да / частично / нет / неприменимо", 3)
    for j, h in enumerate(["№", "Пункт", "Отметка"], 1):
        c = ws.cell(start, j, h)
        c.font = Font(name=FONT, bold=True, color="FFFFFF")
        c.fill = PatternFill("solid", fgColor=BLUE)
        c.alignment = Alignment(horizontal="center")
        c.border = BORDER
    ws.column_dimensions["A"].width = 6
    ws.column_dimensions["B"].width = 80
    ws.column_dimensions["C"].width = 18
    dv = DataValidation(type="list", formula1='"да,частично,нет,неприменимо"', allow_blank=True)
    ws.add_data_validation(dv)
    for i, t in enumerate(CHECK, 1):
        rr = start + i
        ws.cell(rr, 1, i).alignment = Alignment(horizontal="center")
        ws.cell(rr, 2, t).alignment = Alignment(wrap_text=True, vertical="center")
        cc = ws.cell(rr, 3)
        cc.alignment = Alignment(horizontal="center")
        dv.add(cc)
        for j in (1, 2, 3):
            ws.cell(rr, j).border = BORDER
            ws.cell(rr, j).font = Font(name=FONT, size=11)
        ws.row_dimensions[rr].height = 24
    rng = f"C{start + 1}:C{start + len(CHECK)}"
    ws.conditional_formatting.add(rng, CellIsRule(operator="equal", formula=['"да"'], fill=PatternFill("solid", bgColor=GRN_BG), font=Font(color=GRN_TX, bold=True)))
    ws.conditional_formatting.add(rng, CellIsRule(operator="equal", formula=['"нет"'], fill=PatternFill("solid", bgColor=RED_BG), font=Font(color=RED_TX, bold=True)))
    ws.conditional_formatting.add(rng, CellIsRule(operator="equal", formula=['"частично"'], fill=PatternFill("solid", bgColor=AMB_BG), font=Font(color=AMB_TX, bold=True)))
    end = start + len(CHECK) + 2
    ws.cell(end, 2, "Готово («да»):").font = Font(name=FONT, bold=True, color=NAVY)
    ws.cell(end, 3, f'=COUNTIF({rng},"да")&" из {len(CHECK)}"').font = Font(name=FONT, bold=True, color=BLUE)
    footer(ws, end + 2, 3)
    page(ws, landscape=False)

    wb.properties.creator = "ДПО-1 · Клуб «ИИ в образовании»"
    wb.properties.title = "Обезличивание, подделки и дипфейки: как не попасть"
    OUT.mkdir(parents=True, exist_ok=True)
    wb.save(path)
    return path


if __name__ == "__main__":
    print("✓", build())
